def can_see_white_sheet(x1, y1, x2, y2, x3, y3, x4, y4, x5, y5, x6, y6):
    # Check if the white sheet is not covered by any of the black sheets
    def is_outside_black_sheets(px, py):
        # Check if the point (px, py) is outside all black sheets
        return (px < x3 or px > x4 or py < y3 or py > y4) and (px < x5 or px > x6 or py < y5 or py > y6)

    # Check points on the edges of the white sheet
    for px in [x1, x2]:
        for py in range(y1, y2 + 1):
            if is_outside_black_sheets(px, py):
                return "YES"

    for py in [y1, y2]:
        for px in range(x1, x2 + 1):
            if is_outside_black_sheets(px, py):
                return "YES"

    # Check points inside the white sheet
    for px in range(x1 + 1, x2):
        for py in range(y1 + 1, y2):
            if is_outside_black_sheets(px, py):
                return "YES"

    return "NO"

